import{c as r,Q as d,j as o,m as e}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-结构化方法","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-结构化方法"},"headers":[],"relativePath":"综合知识/软件工程/结构化方法.md","filePath":"综合知识/软件工程/结构化方法.md","lastUpdated":null}'),a={name:"综合知识/软件工程/结构化方法.md"};function l(n,t,s,h,g,i){return d(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] DFD 数据流图（分层/平衡原则/常见错误）</li><li>[x] 流程图 vs 数据流图（区别辨析）</li><li>[x] 数据字典（DD）</li><li>[x] 结构化建模三大模型（功能/行为/数据）</li><li>[x] 结构化设计（概要设计/详细设计/模块属性）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、dfd-数据流图-★★" tabindex="-1">一、DFD 数据流图 ★★ <a class="header-anchor" href="#一、dfd-数据流图-★★" aria-label="Permalink to &quot;一、DFD 数据流图 ★★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：DFD 是结构化分析的核心工具，用数据流、加工、数据存储、外部实体四个基本元素描述系统功能模型。</p></blockquote><p><strong>基本元素：</strong></p><table tabindex="0"><thead><tr><th>元素</th><th>表示</th><th>说明</th></tr></thead><tbody><tr><td>数据流</td><td>→</td><td>数据在系统中的移动路径</td></tr><tr><td>加工</td><td>○</td><td>对数据进行的处理/变换</td></tr><tr><td>数据存储</td><td>=</td><td>数据的静态存储</td></tr><tr><td>外部实体</td><td>□</td><td>系统外的人或组织，数据源或数据终点</td></tr></tbody></table><p><strong>分层结构：</strong> 上下文图（顶层）→ 0层图 → 1层图 → …，自顶向下逐层分解。</p><hr><h4 id="dfd-分层平衡原则-★" tabindex="-1">DFD 分层平衡原则 ★ <a class="header-anchor" href="#dfd-分层平衡原则-★" aria-label="Permalink to &quot;DFD 分层平衡原则 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>父图与子图的数据流个数和方向必须一致。</strong></p></blockquote><ul><li><strong>层间平衡</strong>：父图中描述过的数据流必须在相应子图中出现</li><li><strong>图内规则</strong>：每个加工至少有一个输入流和一个输出流</li></ul><hr><h4 id="dfd-常见错误-★★" tabindex="-1">DFD 常见错误 ★★ <a class="header-anchor" href="#dfd-常见错误-★★" aria-label="Permalink to &quot;DFD 常见错误 ★★&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">错误类型</th><th>特征</th><th>考试关键词</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>黑洞</strong></td><td>加工<strong>有输入无输出</strong></td><td>&quot;分类训练只有输入&quot;</td></tr><tr><td style="text-align:left;"><strong>奇迹</strong></td><td>加工<strong>有输出无输入</strong></td><td>&quot;分类处理只有输出&quot;</td></tr><tr><td style="text-align:left;"><strong>灰洞</strong></td><td>输入不足以产生输出</td><td>输入不充分</td></tr><tr><td style="text-align:left;">外部实体→数据存储</td><td>外部实体没有经过加工直接到数据存储</td><td>&quot;规则文件直连&quot;</td></tr><tr><td style="text-align:left;">外部实体→外部实体</td><td>外部实体之间无加工直接有数据流</td><td>&quot;配置信息直连&quot;</td></tr></tbody></table><hr><h4 id="高质量-dfd-三原则" tabindex="-1">高质量 DFD 三原则 <a class="header-anchor" href="#高质量-dfd-三原则" aria-label="Permalink to &quot;高质量 DFD 三原则&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>复杂性最小化、接口最小化、数据流一致性。</strong></p></blockquote><ol><li><strong>复杂性最小化</strong>：信息划分为小而独立子集，逐层查看</li><li><strong>接口最小化</strong>：模型中各元素之间的接口数/连接数最少</li><li><strong>数据流一致性</strong>：父图数据流内容与子图无差异，无黑洞、无奇迹</li></ol><hr><h3 id="二、流程图-vs-数据流图-★" tabindex="-1">二、流程图 vs 数据流图 ★ <a class="header-anchor" href="#二、流程图-vs-数据流图-★" aria-label="Permalink to &quot;二、流程图 vs 数据流图 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>DFD 展现数据流（用于逻辑建模，过程可并行）；流程图展现控制流（用于物理建模，严格顺序）。</strong></p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">对比维度</th><th>数据流图（DFD）</th><th>流程图（Flowchart）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>展示内容</strong></td><td>数据流</td><td>控制流</td></tr><tr><td style="text-align:left;"><strong>处理过程</strong></td><td><strong>可并行</strong></td><td>某时间点只能处于一个处理</td></tr><tr><td style="text-align:left;"><strong>时间标准</strong></td><td>不同过程遵循不同计时标准</td><td>所有过程遵循一致计时标准</td></tr><tr><td style="text-align:left;"><strong>适用阶段</strong></td><td>系统分析 → <strong>逻辑建模</strong></td><td>系统设计 → <strong>物理建模</strong></td></tr></tbody></table><hr><h3 id="三、数据字典-dd-★" tabindex="-1">三、数据字典 DD ★ <a class="header-anchor" href="#三、数据字典-dd-★" aria-label="Permalink to &quot;三、数据字典 DD ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：数据字典对 DFD 中出现的<strong>所有数据元素</strong>进行严格定义和说明的集合。</p></blockquote><p><strong>数据字典内容（4类）：</strong> 数据项、数据结构、数据流、数据存储/基本加工</p><blockquote><p>⚠️ 常见坑：<strong>用户界面</strong>不属于数据字典内容。数据字典是描述数据的，不是描述界面的。</p></blockquote><p><strong>数据字典在分析/设计阶段的作用：</strong></p><ul><li>分析阶段：建立业务概念有组织的集合，是模型核心库，使涉众对元素有共同理解</li><li>设计阶段：根据数据存储描述建立数据库存储设计</li></ul><hr><h3 id="四、结构化建模三大模型-★" tabindex="-1">四、结构化建模三大模型 ★ <a class="header-anchor" href="#四、结构化建模三大模型-★" aria-label="Permalink to &quot;四、结构化建模三大模型 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：<strong>功能模型用 DFD，行为模型用 STD，数据模型用 E-R 图。</strong></p></blockquote><table tabindex="0"><thead><tr><th>模型</th><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><strong>功能模型</strong></td><td>数据流图（DFD）</td><td>系统输入、输出和处理过程</td></tr><tr><td><strong>行为模型</strong></td><td>状态转换图（STD）</td><td>系统状态和引起转换的事件</td></tr><tr><td><strong>数据模型</strong></td><td>E-R 图（实体-关系图）</td><td>数据元素及其关系</td></tr></tbody></table><hr><h3 id="五、结构化设计-★" tabindex="-1">五、结构化设计 ★ <a class="header-anchor" href="#五、结构化设计-★" aria-label="Permalink to &quot;五、结构化设计 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：结构化设计核心是<strong>自顶向下、逐步求精、模块化</strong>。</p></blockquote><p><strong>设计阶段与工具：</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>任务</th><th>工具</th></tr></thead><tbody><tr><td><strong>概要设计</strong></td><td>确定系统结构，划分模块、确定接口和调用关系</td><td><strong>模块结构图（SC）、层次图、HIPO 图</strong></td></tr><tr><td><strong>详细设计</strong></td><td>模块内算法、数据结构、输入/输出/界面设计</td><td>程序流程图（PFD）、N-S 图、PAD、伪代码</td></tr></tbody></table><p><strong>结构化设计提高结构合理性的准则：</strong> 分解与抽象、模块独立性、信息隐蔽</p><blockquote><p>⚠️ 常见坑：数据流图（DFD）不属于这些准则，它是分析工具不是设计准则。<strong>系统结构图 SC 用于概要设计阶段</strong>，不是详细设计阶段。</p></blockquote><p><strong>模块三大基本属性：</strong> 功能、逻辑、状态</p><p><strong>结构化分析的正确顺序：</strong> 先分析业务情况 → 再推导逻辑模型的 DFD。结构化建模核心目的是<strong>描述系统的功能和数据结构</strong>。</p>',43)])])}const c=r(a,[["render",l]]);export{u as __pageData,c as default};
